package scp_candidate.Mining_Threat_Retreat_Supervisor

import org.sireum._
import art.Art
import scp_candidate._

// Do not edit this file as it will be overwritten if HAMR codegen is rerun
@msig trait Mission_Recovery_Decision_supervisor_mr_TestApi {

  def BeforeEntrypoint(): Unit = {
    Art.initTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr)
  }

  def AfterEntrypoint(): Unit = {
    Art.finalizeTest(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr)
  }

  def testCompute(): Unit = {
    Art.manuallyClearOutput()
    Art.testCompute(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr)
  }

  def testInitialise(): Unit = {
    Art.manuallyClearOutput()
    Art.testInitialise(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr)
  }

  /** helper function to set the values of all input ports.
   * @param phase_context payload for data port phase_context
   * @param threat_fact payload for data port threat_fact
   * @param resource_facts payload for data port resource_facts
   * @param mission_facts payload for data port mission_facts
   */
  def put_concrete_inputs(phase_context : Mining_Threat_Retreat_Supervisor.Phase_Context,
                          threat_fact : Mining_Threat_Retreat_Supervisor.Qualified_Threat,
                          resource_facts : Mining_Threat_Retreat_Supervisor.Mining_Recovery_Facts,
                          mission_facts : Mining_Threat_Retreat_Supervisor.Mission_Facts): Unit = {
    put_phase_context(phase_context)
    put_threat_fact(threat_fact)
    put_resource_facts(resource_facts)
    put_mission_facts(mission_facts)
  }


  /** helper function to check Mission_Recovery_Decision_supervisor_mr's
   * output ports.  Use named arguments to check subsets of the output ports.
   * @param mission_proposal method that will be called with the value of the outgoing data
   *        port 'mission_proposal'.
   */
  def check_concrete_output(mission_proposal: Mining_Threat_Retreat_Supervisor.Mission_Proposal => B): Unit = {
    var testFailures: ISZ[ST] = ISZ()

    val mission_proposalValue: Mining_Threat_Retreat_Supervisor.Mission_Proposal = get_mission_proposal().get
    if(!mission_proposal(mission_proposalValue)) {
      testFailures = testFailures :+ st"'mission_proposal' did not match expected: value of the outgoing data port is ${mission_proposalValue}"
    }

    assert(testFailures.isEmpty, st"${(testFailures, "\n")}".render)
  }


  // setter for in DataPort
  def put_phase_context(value : Mining_Threat_Retreat_Supervisor.Phase_Context): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr.operational_api.phase_context_Id, Mining_Threat_Retreat_Supervisor.Phase_Context_Payload(value))
  }

  // setter for in DataPort
  def put_threat_fact(value : Mining_Threat_Retreat_Supervisor.Qualified_Threat): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr.operational_api.threat_fact_Id, Mining_Threat_Retreat_Supervisor.Qualified_Threat_Payload(value))
  }

  // setter for in DataPort
  def put_resource_facts(value : Mining_Threat_Retreat_Supervisor.Mining_Recovery_Facts): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr.operational_api.resource_facts_Id, Mining_Threat_Retreat_Supervisor.Mining_Recovery_Facts_Payload(value))
  }

  // setter for in DataPort
  def put_mission_facts(value : Mining_Threat_Retreat_Supervisor.Mission_Facts): Unit = {
    Art.insertInInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr.operational_api.mission_facts_Id, Mining_Threat_Retreat_Supervisor.Mission_Facts_Payload(value))
  }

  // getter for out DataPort
  def get_mission_proposal(): Option[Mining_Threat_Retreat_Supervisor.Mission_Proposal] = {
    val value: Option[Mining_Threat_Retreat_Supervisor.Mission_Proposal] = get_mission_proposal_payload() match {
      case Some(Mining_Threat_Retreat_Supervisor.Mission_Proposal_Payload(v)) => Some(v)
      case Some(v) => halt(s"Unexpected payload on port mission_proposal.  Expecting 'Mining_Threat_Retreat_Supervisor.Mission_Proposal_Payload' but received ${v}")
      case _ => None[Mining_Threat_Retreat_Supervisor.Mission_Proposal]()
    }
    return value
  }

  // payload getter for out DataPort
  def get_mission_proposal_payload(): Option[Mining_Threat_Retreat_Supervisor.Mission_Proposal_Payload] = {
    return Art.observeOutInfrastructurePort(Arch.Mining_Threat_Retreat_Supervisor_Root_Instance_supervisor_mr.initialization_api.mission_proposal_Id).asInstanceOf[Option[Mining_Threat_Retreat_Supervisor.Mission_Proposal_Payload]]
  }

}
